/// Mnemonic of the test accounts funded by the [`test_genesis`](crate::test_genesis).
pub const TEST_MNEMONIC: &str = "test test test test test test test test test test test junk";

/// One of the accounts of the genesis allocations.
#[derive(Debug)]
pub struct Wallet {
    /// The signer
    pub inner: PrivateKeySigner,
    /// The nonce
    pub inner_nonce: u64,
    /// The chain id
    pub chain_id: u64,
    amount: usize,
}

impl Wallet {
    /// Creates a new account from one of the secret/pubkeys of the genesis allocations (test.json)
    pub fn new(amount: usize) -> Self {
        Self { inner: test_signer(0), chain_id: 1, amount, inner_nonce: 0 }
    }

    /// Sets chain id
    pub const fn with_chain_id(mut self, chain_id: u64) -> Self {
        self.chain_id = chain_id;
        self
    }

    /// Generates a list of wallets
    pub fn wallet_gen(&self) -> Vec<PrivateKeySigner> {
        (0..self.amount as u32).map(|idx| self.signer(idx)).collect()
    }

    /// Returns the signer of the test account at `index`, with the chain id of the wallet.
    pub fn signer(&self, index: u32) -> PrivateKeySigner {
        test_signer(index).with_chain_id(Some(self.chain_id))
    }

    /// Returns the test account at `index`, with the chain id of the wallet and nonce 0.
    pub fn account(&self, index: u32) -> TestAccount {
        TestAccount::new(self.signer(index), self.chain_id)
    }
}

impl Default for Wallet {
    fn default() -> Self {
        Self::new(1)
    }
}

/// Returns the signer of the test account at `index`, derived from [`TEST_MNEMONIC`] with the
/// default Ethereum derivation path `m/44'/60'/0'/0/{index}`.
pub fn test_signer(index: u32) -> PrivateKeySigner {
    MnemonicBuilder::<English>::default()
        .phrase(TEST_MNEMONIC)
        .index(index)
        .expect("valid derivation index")
        .build()
        .expect("valid test mnemonic")
}

/// A test account that tracks its nonce, e.g. one of the accounts funded by the
/// [`test_genesis`](crate::test_genesis).
///
/// [`Self::sign_tx_bytes`] fills the nonce, chain id, gas limit and fees of transaction requests
/// that do not set them, so tests only need to set the fields they care about. The gas limit and
/// fees default to [`Self::DEFAULT_GAS_LIMIT`] and the `DEFAULT_*_FEE_PER_GAS` constants and can be
/// changed once per account with [`Self::with_gas_limit`] and [`Self::with_fees`].
///
/// [`Self::tx`] and its shortcuts [`Self::call`], [`Self::transfer`] and [`Self::deploy`] build and
/// sign a transaction in a single expression:
///
/// ```ignore
/// let mut account = wallet.account(0).with_fees(max_fee_per_gas, max_priority_fee_per_gas);
/// let contract = account.next_contract_address();
/// let deploy = account.deploy(init_code).await;
/// let call = account.call(contract, calldata).gas_limit(100_000).await;
/// ```
#[derive(Debug, Clone)]
pub struct TestAccount {
    signer: PrivateKeySigner,
    chain_id: u64,
    nonce: u64,
    gas_limit: u64,
    max_fee_per_gas: u128,
    max_priority_fee_per_gas: u128,
}

impl TestAccount {
    /// Initial gas limit of transactions signed by [`Self::sign_tx_bytes`] that do not set one.
    pub const DEFAULT_GAS_LIMIT: u64 = 1_000_000;

    /// Initial max fee per gas of transactions signed by [`Self::sign_tx_bytes`] that set no fees.
    ///
    /// High enough that transactions are accepted regardless of the base fee of test chains.
    pub const DEFAULT_MAX_FEE_PER_GAS: u128 = 1_000_000_000_000;

    /// Initial max priority fee per gas of transactions signed by [`Self::sign_tx_bytes`] that set
    /// no fees.
    pub const DEFAULT_MAX_PRIORITY_FEE_PER_GAS: u128 = 1_000_000_000;

    /// Creates a new account for the given signer and chain id, starting at nonce 0.
    pub const fn new(signer: PrivateKeySigner, chain_id: u64) -> Self {
        Self {
            signer,
            chain_id,
            nonce: 0,
            gas_limit: Self::DEFAULT_GAS_LIMIT,
            max_fee_per_gas: Self::DEFAULT_MAX_FEE_PER_GAS,
            max_priority_fee_per_gas: Self::DEFAULT_MAX_PRIORITY_FEE_PER_GAS,
        }
    }

    /// Sets the gas limit of signed transactions that do not set one.
    pub const fn with_gas_limit(mut self, gas_limit: u64) -> Self {
        self.gas_limit = gas_limit;
        self
    }

    /// Sets the EIP-1559 fees of signed transactions that set neither these fees nor a legacy gas
    /// price.
    pub const fn with_fees(
        mut self,
        max_fee_per_gas: u128,
        max_priority_fee_per_gas: u128,
    ) -> Self {
        self.max_fee_per_gas = max_fee_per_gas;
        self.max_priority_fee_per_gas = max_priority_fee_per_gas;
        self
    }

    /// Returns the signer of the account.
    pub const fn signer(&self) -> &PrivateKeySigner {
        &self.signer
    }

    /// Returns the address of the account.
    pub const fn address(&self) -> Address {
        self.signer.address()
    }

    /// Returns the chain id transactions of the account are signed for.
    pub const fn chain_id(&self) -> u64 {
        self.chain_id
    }

    /// Returns the nonce of the next transaction of the account.
    pub const fn nonce(&self) -> u64 {
        self.nonce
    }

    /// Returns the nonce of the next transaction and increments it.
    pub const fn next_nonce(&mut self) -> u64 {
        let nonce = self.nonce;
        self.nonce += 1;
        nonce
    }

    /// Sets the nonce to the pending transaction count of the account on the node behind
    /// `provider`, and returns it.
    pub async fn sync_nonce<N: Network>(
        &mut self,
        provider: &impl Provider<N>,
    ) -> eyre::Result<u64> {
        self.nonce =
            provider.get_transaction_count(self.address()).block_id(BlockId::pending()).await?;
        Ok(self.nonce)
    }

    /// Signs the transaction request, returning the EIP-2718 encoded bytes.
    ///
    /// Fills unset fields: the nonce with [`Self::next_nonce`], the chain id, gas limit and, unless
    /// the request sets a legacy gas price, the EIP-1559 fees of the account. An explicit nonce
    /// does not advance the tracked nonce. Contract creations must set `to`, e.g. with
    /// [`TransactionRequest::create`] or [`Self::deploy`].
    ///
    /// See [`Self::sign_request`] for other networks.
    ///
    /// # Panics
    ///
    /// If the request can not be built into a signed transaction.
    pub async fn sign_tx_bytes(&mut self, tx: TransactionRequest) -> Bytes {
        self.sign_request::<Ethereum>(tx).await
    }

    /// Returns the address of the contract created by the next transaction of the account, if it
    /// is a contract creation that does not set an explicit nonce.
    pub fn next_contract_address(&self) -> Address {
        self.address().create(self.nonce)
    }

    /// Starts building a transaction of the account that sets no fields yet.
    ///
    /// See [`Self::tx_for`] for other networks.
    pub fn tx(&mut self) -> TestTx<'_> {
        self.tx_for()
    }

    /// Starts building a call of `to` with the given input.
    pub fn call(&mut self, to: Address, input: impl Into<Bytes>) -> TestTx<'_> {
        self.tx().to(to).input(input)
    }

    /// Starts building a transfer of `value` to `to`.
    pub fn transfer(&mut self, to: Address, value: U256) -> TestTx<'_> {
        self.tx().to(to).value(value)
    }

    /// Starts building a contract creation with the given init code.
    ///
    /// See [`Self::next_contract_address`] for the address of the created contract.
    pub fn deploy(&mut self, init_code: impl Into<Bytes>) -> TestTx<'_> {
        self.tx().create().input(init_code)
    }

    /// Signs the transaction request of the network `N` like [`Self::sign_tx_bytes`], returning
    /// the EIP-2718 encoded bytes.
    ///
    /// Only the secp256k1 key of the account signs, so transactions of networks that are signed
    /// with other keys, e.g. P256 or passkeys, need their own wallets. Transactions using a
    /// network-specific nonce scheme, such as 2D nonces, should set an explicit nonce so that the
    /// tracked protocol nonce is not advanced.
    ///
    /// # Panics
    ///
    /// If the request can not be built into a signed transaction.
    pub async fn sign_request<N: Network>(&mut self, mut tx: N::TransactionRequest) -> Bytes
    where
        EthereumWallet: NetworkWallet<N>,

//! Canonical chain state notification trait and types.

use alloy_eips::BlockNumHash;
use derive_more::{Deref, DerefMut};
use reth_execution_types::{BlockReceipts, Chain};
use reth_primitives_traits::{NodePrimitives, RecoveredBlock, SealedHeader};
use std::{
    pin::Pin,
    sync::Arc,
    task::{ready, Context, Poll},
};
use tokio::sync::{broadcast, watch};
use tokio_stream::{
    wrappers::{BroadcastStream, WatchStream},
    Stream,
};
use tracing::debug;

/// Type alias for a receiver that receives [`CanonStateNotification`]
pub type CanonStateNotifications<N = reth_ethereum_primitives::EthPrimitives> =
    broadcast::Receiver<CanonStateNotification<N>>;

/// Type alias for a sender that sends [`CanonStateNotification`]
pub type CanonStateNotificationSender<N = reth_ethereum_primitives::EthPrimitives> =
    broadcast::Sender<CanonStateNotification<N>>;

/// A type that allows to register chain related event subscriptions.
pub trait CanonStateSubscriptions: Send + Sync {
    /// The node primitive types.
    type Primitives: NodePrimitives;

    /// Get notified when a new canonical chain was imported.
    ///
    /// A canonical chain be one or more blocks, a reorg or a revert.
    fn subscribe_to_canonical_state(&self) -> CanonStateNotifications<Self::Primitives>;

    /// Convenience method to get a stream of [`CanonStateNotification`].
    fn canonical_state_stream(&self) -> CanonStateNotificationStream<Self::Primitives> {
        CanonStateNotificationStream {
            st: BroadcastStream::new(self.subscribe_to_canonical_state()),
        }
    }
}

impl<T: CanonStateSubscriptions> CanonStateSubscriptions for &T {
    type Primitives = T::Primitives;

    fn subscribe_to_canonical_state(&self) -> CanonStateNotifications<Self::Primitives> {
        (*self).subscribe_to_canonical_state()
    }

    fn canonical_state_stream(&self) -> CanonStateNotificationStream<Self::Primitives> {
        (*self).canonical_state_stream()
    }
}

/// A Stream of [`CanonStateNotification`].
#[derive(Debug)]
#[pin_project::pin_project]
pub struct CanonStateNotificationStream<N: NodePrimitives = reth_ethereum_primitives::EthPrimitives>
{
    #[pin]
    st: BroadcastStream<CanonStateNotification<N>>,
}

impl<N: NodePrimitives> Stream for CanonStateNotificationStream<N> {
    type Item = CanonStateNotification<N>;

    fn poll_next(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        loop {
            return match ready!(self.as_mut().project().st.poll_next(cx)) {
                Some(Ok(notification)) => Poll::Ready(Some(notification)),
                Some(Err(err)) => {
                    debug!(%err, "canonical state notification stream lagging behind");
                    continue
                }
                None => Poll::Ready(None),
            }
        }
    }
}

/// A notification that is sent when a new block is imported, or an old block is reverted.
///
/// The notification contains at least one [`Chain`] with the imported segment. If some blocks were
/// reverted (e.g. during a reorg), the old chain is also returned.
#[derive(Clone, Debug, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(feature = "serde", serde(bound = ""))]
pub enum CanonStateNotification<N: NodePrimitives = reth_ethereum_primitives::EthPrimitives> {
    /// The canonical chain was extended.
    Commit {
        /// The newly added chain segment.
        new: Arc<Chain<N>>,
    },
    /// A chain segment was reverted or reorged.
    ///
    /// - In the case of a reorg, the reverted blocks are present in `old`, and the new blocks are
    ///   present in `new`.
    /// - In the case of a revert, the reverted blocks are present in `old`, and `new` is an empty
    ///   chain segment.
    Reorg {
        /// The chain segment that was reverted.
        old: Arc<Chain<N>>,
        /// The chain segment that was added on top of the canonical chain, minus the reverted
        /// blocks.
        ///
        /// In the case of a revert, not a reorg, this chain segment is empty.
        new: Arc<Chain<N>>,
    },
}

impl<N: NodePrimitives> CanonStateNotification<N> {
    /// Get the chain segment that was reverted, if any.
    pub fn reverted(&self) -> Option<Arc<Chain<N>>> {
        match self {
            Self::Commit { .. } => None,
            Self::Reorg { old, .. } => Some(old.clone()),
        }
    }

    /// Get the newly imported chain segment, if any.
    pub fn committed(&self) -> Arc<Chain<N>> {
        match self {
            Self::Commit { new } | Self::Reorg { new, .. } => new.clone(),
        }
    }

    /// Gets the new tip of the chain.
    ///
    /// Returns the new tip for [`Self::Reorg`] and [`Self::Commit`] variants which commit at least
    /// 1 new block.
    ///
    /// # Panics
    ///
    /// If chain doesn't have any blocks.
    pub fn tip(&self) -> &RecoveredBlock<N::Block> {
        match self {
            Self::Commit { new } | Self::Reorg { new, .. } => new.tip(),
        }
    }

    /// Gets the new tip of the chain.
    ///
    /// If the chain has no blocks, it returns `None`. Otherwise, it returns the new tip for
    /// [`Self::Reorg`] and [`Self::Commit`] variants.
    pub fn tip_checked(&self) -> Option<&RecoveredBlock<N::Block>> {
        match self {
            Self::Commit { new } | Self::Reorg { new, .. } => {
                if new.is_empty() {
                    None
                } else {
                    Some(new.tip())
                }
            }
        }
    }

    /// Get receipts in the reverted and newly imported chain segments with their corresponding
    /// block numbers and transaction hashes.
    ///
    /// The boolean in the tuple (2nd element) denotes whether the receipt was from the reverted
    /// chain segment.
    pub fn block_receipts(&self) -> Vec<(BlockReceipts<N::Receipt>, bool)> {
        let mut receipts = Vec::new();

        // get old receipts
        if let Some(old) = self.reverted() {
            receipts
                .extend(old.receipts_with_attachment().into_iter().map(|receipt| (receipt, true)));
        }
        // get new receipts
        receipts.extend(
            self.committed().receipts_with_attachment().into_iter().map(|receipt| (receipt, false)),
        );
        receipts
    }
}

/// Wrapper around a broadcast receiver that receives fork choice notifications.
#[derive(Debug, Deref, DerefMut)]
pub struct ForkChoiceNotifications<T = alloy_consensus::Header>(
    pub watch::Receiver<Option<SealedHeader<T>>>,
);

/// A trait that allows to register to fork choice related events
/// and get notified when a new fork choice is available.
pub trait ForkChoiceSubscriptions: Send + Sync {
    /// Block Header type.
    type Header: Clone + Send + Sync + 'static;

    /// Get notified when a new safe block of the chain is selected.
    fn subscribe_safe_block(&self) -> ForkChoiceNotifications<Self::Header>;

    /// Get notified when a new finalized block of the chain is selected.
    fn subscribe_finalized_block(&self) -> ForkChoiceNotifications<Self::Header>;

    /// Convenience method to get a stream of the new safe blocks of the chain.
    fn safe_block_stream(&self) -> ForkChoiceStream<SealedHeader<Self::Header>> {
        ForkChoiceStream::new(self.subscribe_safe_block().0)
    }

    /// Convenience method to get a stream of the new finalized blocks of the chain.
    fn finalized_block_stream(&self) -> ForkChoiceStream<SealedHeader<Self::Header>> {
        ForkChoiceStream::new(self.subscribe_finalized_block().0)
    }
}

/// A stream that yields values from a `watch::Receiver<Option<T>>`, filtering out `None` values.
#[derive(Debug)]
#[pin_project::pin_project]
pub struct WatchValueStream<T> {
    #[pin]
    st: WatchStream<Option<T>>,
}

impl<T: Clone + Sync + Send + 'static> WatchValueStream<T> {
    /// Creates a new [`WatchValueStream`]
    pub fn new(rx: watch::Receiver<Option<T>>) -> Self {
        Self { st: WatchStream::from_changes(rx) }
    }
}

impl<T: Clone + Sync + Send + 'static> Stream for WatchValueStream<T> {
    type Item = T;

    fn poll_next(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        loop {
            match ready!(self.as_mut().project().st.poll_next(cx)) {
                Some(Some(notification)) => return Poll::Ready(Some(notification)),
                Some(None) => {}
                None => return Poll::Ready(None),
            }
        }
    }
}

/// Alias for [`WatchValueStream`] for fork choice watch channels.
pub type ForkChoiceStream<T> = WatchValueStream<T>;

use crate::{
    maintain::MAX_QUEUED_TRANSACTION_LIFETIME,
    pool::{NEW_TX_LISTENER_BUFFER_SIZE, PENDING_TX_LISTENER_BUFFER_SIZE},
